spec.expr:
100 *
avg_over_time(
  (
    (
      100 *
      (
        (
          sum(
            increase(
              cadence_errors{
                deployment=~"$deployment",
                cadence_service=~"cadence[-_]frontend",
                operation=~"(Start|Signal|SignalWithStart)WorkflowExecution",
                signalname!~".+"
              }[15m]
            )
          ) or vector(0)
        )
        /
        sum(
          increase(
            cadence_requests{
              deployment=~"$deployment",
              cadence_service=~"cadence[-_]frontend",
              operation=~"(Start|Signal|SignalWithStart)WorkflowExecution",
              signalname!~".+"
            }[15m]
          )
        )
      )
    )
    <= bool 1
  )[1h:15m]
)

label_replace(
  min_over_time(
    (
      100 * (
        1 -
        (
          (
            sum by (cadence_service) (
              rate(
                cadence_errors{
                  deployment=~"$deployment",
                  cadence_service=~"cadence[-_].*"
                }[$__rate_interval:$__interval]
              )
            )
            or on (cadence_service)
            (
              sum by (cadence_service) (
                rate(
                  cadence_requests{
                    deployment=~"$deployment",
                    cadence_service=~"cadence[-_].*"
                  }[$__rate_interval:$__interval]
                )
              ) * 0
            )
          )
          /
          sum by (cadence_service) (
            rate(
              cadence_requests{
                deployment=~"$deployment",
                cadence_service=~"cadence[-_].*"
              }[$__rate_interval:$__interval]
            )
          )
        )
      )
    )[$summarize:]
  ),
  "cadence_service",
  "$1",
  "cadence_service",
  "cadence[-_](.*)"
)

