min_over_time(
  (
    100 * (
      1 - (
        (
          (sum(rate(persistence_errors{deployment=~"$deployment"}[$__rate_interval])) or vector(0))
          +
          (sum(rate(persistence_errors_rollup{deployment=~"$deployment"}[$__rate_interval])) or vector(0))
